/**
 * 主站语言基础设施
 *
 * 口径与红线：
 * - **英文是默认语言，路径不变**（`/pricing/`），已收录的英文 URL 不受影响 —— 这是 SEO 底线。
 * - 非英文一律走**前缀式路径** `/zh/pricing/`。选前缀而不是子域名：
 *   ① 子域要单独过 DNS + SSL + 站长验证，运维成本高；
 *   ② 前缀能把所有语言版本收在同一域下，权重集中、hreflang 关系最简单；
 *   ③ CF Pages 一个项目就能发全站，不需要多套部署配置。
 * - 🔴 **语言 ≠ 顾客语言**。这里只服务「用某语言找产品的商家」，
 *   顾客侧召回模板的多语言是另一件事（见 cart DESIGN.md §15.3），两者别混。
 * - 🔴 **cart-rescue/ 下 4 个页面是旧链接兼容桩，不参与本地化** —— 翻译会打断
 *   App Store / Partner 旧链接的跳转，这是线上真实依赖。
 *
 * 🔴🔴 **2026-11-10 用户裁决：为主站添加中文，后续约需五种语言；同日追加德 / 法 / 西 / 日**
 *    ⇒ **本裁决覆盖 2026-10-12「主站只做英文」**（按「最新裁决优先 + 显式记账冲突」，
 *      旧裁决原文不静默删除，作为历史保留在下方）。10-12 的 GA4 门槛条件
 *      （该语言需有真实自然搜索量 + 跳出率可接受）**不再作为加语言的前置条件**；
 *      本次为战略决定，不是流量数据结论。
 *    ⇒ 语种已全部明确：`en`（默认） + `zh` / `de` / `fr` / `es` / `ja` = **6 语**，
 *      正好是「约五种语言」的完整落地。此前未定的 4 个槽位已一次性补齐，
 *      不再预留空壳语言。
 *
 *    **旧裁决（2026-10-12，已被覆盖）**：曾取代 2026-10-08 的「en/de/fr 三种够了」。
 *      理由是德/法语上线后 GA4 无成规模搜索词、结构大改期 ×3 人工核对成本过高，
 *      ⇒ 先收敛成单语把页数做上去。`/de/*`、`/fr/*` 因此由 `static/_redirects`
 *      301 回英文页（docs 域走 GitHub Pages，那侧忽略该文件，本就没有 de/fr 页面）。
 *      🟢 11-10 恢复 de/fr 时**已删除那 4 条 301** —— 不删会把新生成的页面重定向吃掉
 *      （护栏会在 prebuild 阻断）。es/ja 从未上线过，本就没有历史 301。
 *
 *    🟢 **多语言整体设计**：**`LOCALES` 是唯一开关**，加语言不改页面/路由/SEO/切换器。
 *      - 路由：`gatsby-node.js` 的 `onCreatePage` 遍历 `LOCALES` 自动生成 `/<prefix>/*`。
 *      - 链接：`localePath()` 只给 `LOCALIZED_PAGES` 里的路径加前缀，未本地化页留英文原路径。
 *      - SEO：`SEO` 组件按 `LOCALES` 自动扩 hreflang / og:locale:alternate / x-default。
 *      - 切换器：`LanguageSwitcher` 遍历 `LOCALES`，不硬编码任何语言名。
 *      - 字典：`dictionaries/*.js` 以 `en` 为**契约真源**，每种语言一块；
 *        `scripts/check-i18n.mjs` 在 `prebuild` 校验 key / 数组长度 / 占位符 / 数字口径 /
 *        HTML 标签 / 301 冲突，漂移即阻断构建 —— 6 语规模下这是唯一能防住
 *        「漏翻默默上英文」与「数字口径被译文改掉」的机制。
 *      ⇒ **加一种语言 = ① `LOCALES` 加一条 ② 7 份字典补该语言块 ③ 若 `static/_redirects`
 *        有该前缀的 301 规则则删掉 ④ `npm run build`（护栏自动跑 + 产物出证）**。
 *
 * 🔴🔴 **2026-11-12 用户裁决「批量扩页」**：本地化范围由 5 页扩到 **21 页**
 *    （导航 3 项 + 页脚高频页 + 平台侧内页 + status/changelog/sitemap）。
 *    新增 `dictionaries/innerPages.js` 段落级字典与 `i18n/LocalizedText.js` 的 `<T>`
 *    组件：内联元素用 `{0}` 占位符留在段落模板里，译文可重排语序，页面结构零改动。
 *    ⚠️ 仍未纳入：`src/data/*.js` 数据驱动的族子页（integrations/guides/help/features/
 *    industries/use-cases/compare/solutions 的详情页）、privacy/terms/gdpr 法务长文、
 *    cart-rescue/* 兼容桩、404。这些页只有英文路径，站内链接会回英文原路径 ——
 *    **刻意不生成前缀路由**：给内容全英文的页套语言前缀 + hreflang，等于向搜索引擎
 *    声明并不存在的译文版，比诚实留在英文路径更糟。下一批扩页须连同 `src/data/*`
 *    的文案一起字典化，不能只加路由。
 *
 * @author 恒哥
 */

/** 已启用的语言。未在此列出的语言一律回退英文。 */
export const LOCALES = {
  en: {
    code: 'en',
    /** html lang 属性（同时用作 hreflang 值） */
    htmlLang: 'en',
    /** Open Graph locale */
    ogLocale: 'en_US',
    /** 路径前缀。空 = 默认语言，路径不变 */
    prefix: '',
    /** 语言切换器上的显示名（用**该语言自称**，不写 English） */
    nativeName: 'English',
    /** 面包屑/切换器旁的语言标签 */
    label: 'English',
    /** 语言切换器收起态的短标签（导航栏有硬宽度预算，越短越好） */
    shortLabel: 'EN',
  },
  zh: {
    code: 'zh',
    /** hreflang / html lang 用 `zh-CN`；不用 `zh-Hans`，与既有中文内容口径一致 */
    htmlLang: 'zh-CN',
    /** og:locale 用下划线格式 */
    ogLocale: 'zh_CN',
    prefix: '/zh',
    nativeName: '中文',
    label: '中文',
    shortLabel: '中文',
  },
  de: {
    code: 'de',
    htmlLang: 'de',
    ogLocale: 'de_DE',
    /** 🟢 历史前缀：2026-10-08～10-12 德文站就用 `/de`，恢复后旧收录 URL 直接可用 */
    prefix: '/de',
    nativeName: 'Deutsch',
    label: 'Deutsch',
    shortLabel: 'DE',
  },
  fr: {
    code: 'fr',
    htmlLang: 'fr',
    ogLocale: 'fr_FR',
    /** 同上，历史前缀 `/fr` */
    prefix: '/fr',
    nativeName: 'Français',
    label: 'Français',
    shortLabel: 'FR',
  },
  es: {
    code: 'es',
    htmlLang: 'es',
    ogLocale: 'es_ES',
    prefix: '/es',
    nativeName: 'Español',
    label: 'Español',
    shortLabel: 'ES',
  },
  ja: {
    code: 'ja',
    htmlLang: 'ja',
    ogLocale: 'ja_JP',
    prefix: '/ja',
    nativeName: '日本語',
    label: '日本語',
    shortLabel: 'JA',
  },
};

export const DEFAULT_LOCALE = 'en';

/**
 * 已本地化的页面（与 src/pages 下的路径一致）。
 *
 * 🟢 **2026-11-12 批量扩页后共 21 页**：`LOCALES` 6 语（默认 `en` + 5 前缀），
 *    `gatsby-node.js` 按本清单生成 **21 × 5 = 105 条前缀路由**。
 *    ⚠️ **每加一种语言 / 每加一个页面都要重新核对本清单**（页面增减、字典缺失、路径漂移）。
 *
 * 🔴 这份清单是**单一真源**，被三处消费：
 *   ① `gatsby-node.onCreatePage` 据此生成 `/<prefix>/*` 路由；
 *   ② `localePath()` 据此决定站内路径**该不该加语言前缀**；
 *   ③ `SEO` 据此决定**是否输出 hreflang**（只有真的存在译文版才输出）。
 *   不在清单里的页面一律指向英文原路径，绝不能加前缀，否则点导航就撞 404。
 *   （德语页曾产生 5 条死链：/de/customers、/de/help、/de/about、/de/privacy、
 *     /de/terms —— 导航与页脚全在。教训：语言前缀不能无脑加。）
 *
 * 🔴🔴 **2026-11-12 语义收紧：`isLocalizedPath()` 改为精确匹配，不再是 `startsWith`**。
 *    此前清单只有 5 条叶子页，前缀匹配没有副作用；批量扩页后清单包含
 *    `/integrations/`、`/guides/`、`/help/`、`/solutions/`、`/platform/` 这类**索引页**，
 *    继续用 startsWith 会把 `src/data/*.js` 生成的几十个子页也一并克隆出前缀路由，
 *    而那些模板页根本不读字典 ⇒ 产出「URL 带 /de/、正文全英文」的假译文页，
 *    hreflang 还会把它们声明成真实译文版本，SEO 上是自相矛盾。
 *    ⇒ 索引页本地化**不代表其族子页本地化**；要扩子页必须连同 data 文案一起字典化。
 *
 * 🔴 刻意**不含**：cart-rescue/*（App Store / Partner 旧链接兼容桩，useEffect 里 navigate，
 *    翻译会打断跳转）、404、privacy/terms/gdpr 法务长文、以及所有数据驱动族子页。
 */
export const LOCALIZED_PAGES = [
  // 首轮 5 页（2026-11-10）
  '/',
  '/pricing/',
  '/install/',
  '/products/',
  '/features/ai-email-engine/',
  // 2026-11-12 批量扩页：导航 3 项 + 页脚高频页
  '/about/',
  '/platform/',
  '/integrations/',
  '/customers/',
  '/faq/',
  '/contact/',
  '/security/',
  '/guides/',
  '/help/',
  '/solutions/',
  // 平台侧内页 + 运营页
  '/platform/pricing/',
  '/platform/roadmap/',
  '/platform/sms/',
  '/status/',
  '/changelog/',
  '/sitemap/',
];

/**
 * 该站内路径是否已本地化。
 * @param {string} path 英文视角的路径
 * @returns {boolean}
 */
export function isLocalizedPath(path) {
  const raw = path && path.startsWith('/') ? path : `/${path || ''}`;
  // 🔴 尾斜杠归一化：清单里写的是 `/pricing/`，而页面传给 SEO 的是 `/pricing`
  //    （少一个斜杠）。不归一化就会匹配失败 ⇒ localePath 不加语言前缀 ⇒
  //    canonical 与三条 hreflang 全部指向英文路径，等于告诉搜索引擎
  //    「/de/pricing/、/fr/pricing/、/pricing/ 是同一个页面」，多语言信号作废。
  //    这个 bug 此前只因首页走 `p === '/'` 的特例而没被发现。
  const p = raw.length > 1 && !raw.endsWith('/') ? `${raw}/` : raw;
  // 🔴 精确匹配（2026-11-12）：批量扩页后清单里有索引页，改用 startsWith 会把
  //    数据驱动的族子页（/integrations/<slug>/、/guides/<slug>/ …）一并判为已本地化，
  //    克隆出「有前缀、正文仍英文」的假译文页并输出错误 hreflang。详见清单上方说明。
  return LOCALIZED_PAGES.some((lp) => (lp === '/' ? p === '/' : p === lp));
}

/** 站点支持的全部语言 code，hreflang 用 */
export const LOCALE_CODES = Object.keys(LOCALES);

/**
 * 从 pathname 判断当前语言与去掉前缀后的路径。
 *
 * @param {string} pathname 例如 `/de/pricing/`
 * @returns {{locale: string, basePath: string}} locale 为 LOCALES 的 key；
 *   basePath 是不含语言前缀的站内路径（英文视角），用于拼「当前页的各语言版本」
 */
export function resolveLocale(pathname) {
  if (!pathname || typeof pathname !== 'string') {
    return { locale: DEFAULT_LOCALE, basePath: '/' };
  }
  // 逐个匹配前缀，避免 /de 与 /dev-tools 之类的前缀误伤
  for (const code of LOCALE_CODES) {
    const { prefix } = LOCALES[code];
    if (!prefix) continue;
    if (pathname === prefix || pathname === `${prefix}/` || pathname.startsWith(`${prefix}/`)) {
      return { locale: code, basePath: pathname.slice(prefix.length) || '/' };
    }
  }
  return { locale: DEFAULT_LOCALE, basePath: pathname };
}

/**
 * 给站内路径加上语言前缀。
 *
 * 🔴 **未本地化的页面不加前缀** —— 它们只有英文版，加前缀会得到 404。
 *    典型场景：德语页的导航/页脚指向 `/customers/`，若一律加前缀就变成
 *    `/de/customers/` ⇒ 点导航即撞墙（本仓真实发生过）。判据是
 *    {@link LOCALIZED_PAGES}，那份清单与 gatsby-node 生成路由用的是同一份。
 *
 * @param {string} path 英文视角的路径，如 `/pricing/`
 * @param {string} locale 语言 code
 * @returns {string} 已本地化 → `/de/pricing/`；未本地化或英文 → 原路径
 */
export function localePath(path, locale) {
  const cfg = LOCALES[locale];
  const raw = path && path.startsWith('/') ? path : `/${path || ''}`;
  // 统一补尾斜杠：Gatsby 的真实 URL 都带尾斜杠，canonical / hreflang / <Link to>
  // 若指向无斜杠版本，等于告诉搜索引擎这个 URL 不存在（与站内实际链接也不一致）。
  const normalized = raw.length > 1 && !raw.endsWith('/') ? `${raw}/` : raw;
  if (!cfg || !cfg.prefix) return normalized;
  // 已经是带前缀的路径则不重复加
  if (
    LOCALE_CODES.some((c) => LOCALES[c].prefix && normalized.startsWith(`${LOCALES[c].prefix}/`))
  ) {
    return normalized;
  }
  // 该页没有对应语言版本 ⇒ 留在英文原路径，不要造出 404
  if (!isLocalizedPath(normalized)) return normalized;
  return `${cfg.prefix}${normalized === '/' ? '/' : normalized}`;
}

/** 只合并普通对象；数组整体替换（数组必须逐条对应，由 prebuild 护栏校验长度）。 */
function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function mergeDeep(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return override === undefined ? base : override;
  }
  const out = { ...base };
  Object.keys(override).forEach((key) => {
    out[key] = key in base ? mergeDeep(base[key], override[key]) : override[key];
  });
  return out;
}

/**
 * 取当前语言的字典（**深合并**英文兜底）。
 *
 * 🔴 2026-11-10 由浅合并改为深合并：原实现 `{ ...fallback, ...dict }` 只合并顶层，
 *    若某语言只写了 `nav.home`，整个 `nav` 对象会被替换 ⇒ 其余导航项全部 `undefined`。
 *    六语规模下这是最容易发生、又最难在页面上发现的漂移。
 *    ⚠️ 深合并只是兜底，**不等于允许漏翻**：`scripts/check-i18n.mjs` 在 `prebuild`
 *    强制校验每种语言的 key / 数组长度 / 占位符 / 数字口径与 `en` 完全一致，
 *    缺 key 直接阻断构建，不会靠运行时回退悄悄变成英文。
 *
 * @param {string} locale 语言 code
 * @param {object} dictionaries 全语言字典表
 * @returns {object}
 */
export function getDictionary(locale, dictionaries) {
  const fallback = dictionaries[DEFAULT_LOCALE] || {};
  if (locale === DEFAULT_LOCALE) return fallback;
  const dict = dictionaries[locale];
  if (!dict) return fallback;
  return mergeDeep(fallback, dict);
}
