/**
 * 渐进式文案层（2026-11-12，zh / fr 收尾）
 *
 * 解决的问题
 * ──────────
 * 字典层（dictionaries/*.js）与段落层（LocalizedText + innerPages.js）已经覆盖
 * 了页面里写死的 JSX 文案，但仍有三类英文会漏到 /zh/、/fr/ 的静态 HTML 里：
 *
 *   ① `src/data/*.js` 驱动的卡片文案 —— `{g.title}` / `{i.summary}` / `{c.story}`
 *      在页面里是直接作为 React children 渲染的，外面没有 <T>；
 *   ② `<T>` 段落里作为**插槽**塞回去的内联节点，例如
 *      `<strong>A send log for every message.</strong>` —— 段落模板被翻译了，
 *      插槽里的英文原样插回；
 *   ③ 每页硬编码的 `<SEO title="…" description="…" />` 属性，以及页脚常量。
 *
 * 这三类共 278 条，散落在 20 个页面、10 份 data 文件、若干常量里，逐个包 <T>
 * 要改上百处且很容易漏。本层采用「英文原文即 key」的**渐进字典**：
 *
 *   - 命中 → 返回 zh / fr 译文；
 *   - 未命中 → **原样返回**（因此 en / de / es / ja 行为零变化，英文页也不会
 *     因为字典里多了一条而变样）；
 *   - 只加 zh / fr 两块，将来补齐其它语言只是往 JSON 里加块，不改任何组件。
 *
 * 🔴 为什么不把 data/*.js 改成按语言分块的结构：那 10 份文件合计 4767 行，
 *    且被大量非本地化页（英文-only 的族页）共享，改动面大、回归风险高。
 *    以英文原文为 key 是**附加层**，不改既有数据结构，缺译文自动降级英文。
 *
 * 🔴 key 由 `scripts/extract-pending.mjs` 从**构建产物的可见文本**抽取、
 *    `scripts/build-datacopy.mjs` 生成，禁止手抄（弯引号 / 长破折号 /
 *    模板拼接后的数字，手抄必然漂移，且漂移表现为「静默不翻译」）。
 *
 * @author 恒哥
 */
import raw from './dictionaries/dataCopy.json';

export const DATA_COPY = raw;

/** 有译文块的语言。没有块的语言直接短路，连一次字符串归一化都不做。 */
export function hasDataCopy(locale) {
  return Object.prototype.hasOwnProperty.call(raw, locale);
}

/** 空白归一：JSX 里的换行 / 缩进与 HTML textContent 的空格不一样。 */
const normalize = (s) => s.replace(/\s+/g, ' ').trim();

/** 标点折叠：弯引号、长短破折号、省略号在源码与产物里可能不同形。 */
const fold = (s) =>
  normalize(s)
    .replace(/[’‘`´]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[—–−]/g, '-')
    .replace(/…/g, '...')
    .replace(/\u00a0/g, ' ');

/**
 * 预建三级索引：精确 → 空白归一 → 标点折叠。
 * 放在模块加载期做一次，dc() 在渲染期只是 3 次对象查找。
 */
function buildIndex(map) {
  const normalized = Object.create(null);
  const folded = Object.create(null);
  for (const [key, value] of Object.entries(map)) {
    const n = normalize(key);
    const f = fold(key);
    if (normalized[n] === undefined) normalized[n] = value;
    if (folded[f] === undefined) folded[f] = value;
  }
  return { exact: map, normalized, folded };
}

const INDEX = Object.fromEntries(
  Object.entries(raw).map(([locale, map]) => [locale, buildIndex(map)])
);

/**
 * 翻译一段英文文案。纯函数，SSR / 客户端结果一致（locale 来自 pageContext）。
 *
 * @param {string} text 英文原文
 * @param {string} locale 当前语言 code
 * @returns {string} 译文，或原文（未命中 / 无该语言字典）
 */
export function dc(text, locale) {
  if (typeof text !== 'string' || !text || !hasDataCopy(locale)) return text;
  const idx = INDEX[locale];
  const hit = idx.exact[text];
  if (hit !== undefined) return hit;
  const n = normalize(text);
  if (n === text) {
    const byFold = idx.folded[fold(n)];
    return byFold === undefined ? text : byFold;
  }
  const byNorm = idx.normalized[n];
  if (byNorm !== undefined) return byNorm;
  const byFold = idx.folded[fold(n)];
  return byFold === undefined ? text : byFold;
}

/**
 * 页面组件用的便捷钩子：返回绑定了当前语言的翻译函数。
 * 刻意**不**用 React Context —— 页面组件渲染在 I18nProvider 之外（见
 * src/i18n/index.js 的 usePageI18n 说明），Context 会拿到默认值 en。
 *
 * @param {string} locale
 * @returns {(text: string) => string}
 */
export function bindDc(locale) {
  if (!hasDataCopy(locale)) return (text) => text;
  return (text) => dc(text, locale);
}
